mapper.update:
update t_smart_job
set deleted = #{deleted, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}
where job_id = #{jobId}

mapper.select:
SELECT *
FROM t_smart_job


        AND ( job_name ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR job_class ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR trigger_value ILIKE CONCAT('%', #{query.searchWord}, '%')
        )


        AND trigger_type = #{query.triggerType}


        AND enabled = #{query.enabledFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}


        AND deleted = #{query.deleted, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}



    ORDER BY sort ASC,job_id DESC
